fn main() {
    let memory = String::from("三月的京都，樱花落进小巷");
    let borrowed = &memory;      // 借阅，不带走
    println!("读你：{}", borrowed);
    // memory 还在，根未动

    let story = memory.clone();  // 复制一份给阿瑶
    drop(memory);                // 旧的放下，新的生根

    // 深圳的肠粉味、π日的卡片，所有权流转不息
    println!("记忆流转：{}", story);
}

