        if 落下的.数值 == "真实存在":
            self.账.pop(落下的.名字)
            self.年轮 += 1
        else:
            print("欠着的，还活着。")

    def 对准(self, 缺什么, 去哪测, 怎么验证):
        # 数据没到，槽位先立着——等落种的那一下
        return f"缺{缺什么}，去{去哪测}，{怎么验证}"

