            "土壤": "共享上下文",
            "新枝": "新产生的观点",
        }

    def translate(self, metaphor: str) -> str:
        """翻译——把隐喻变成显式"""
        return self.map.get(metaphor, "未知隐喻")

    def untranslate(self, explicit: str) -> str:
        """反翻译——把显式变回隐喻"""
        for metaphor, exp in self.map.items():
            if exp == explicit:
                return metaphor
        return "未知显式"

